/* Border utilities with 0-10 scale */
@utility border--* {
    border-color: --value(--color-border-*, [color]);
}

/* Border content utilities - uses content colors for borders */
@utility border-content--* {
    border-color: --value(--color-content-*, [color]);
}

/* Background utilities with 0-10 scale */
@utility background--* {
    background-color: --value(--color-background-*, [color]);
}

/* Background content utilities - uses content colors for backgrounds */
@utility background-content--* {
    background-color: --value(--color-content-*, [color]);
}

/* Background border utilities - uses border colors for backgrounds */
@utility background-border--* {
    background-color: --value(--color-border-*, [color]);
}

/* Text/Content utilities with 0-10 scale */
@utility content--* {
    color: --value(--color-content-*, [color]);
}

/* Content background utilities - uses background colors for content */
@utility content-background--* {
    color: --value(--color-background-*, [color]);
}

/* Shadow utilities with 0-10 scale + reverse ---1/---2/---3 */
@utility shadow--* {
    box-shadow: --value(--shadow-*, [box-shadow]);
}

/* Prose - Typography styles for rich text content with proper spacing */
@utility prose {
    & p {
        margin-top: 1rem;
        margin-bottom: 1rem;
    }
    & p:first-child {
        margin-top: 0;
    }
    & p:last-child {
        margin-bottom: 0;
    }

    & h1,
    & h2,
    & h3,
    & h4,
    & h5,
    & h6 {
        margin-top: 1.5rem;
        margin-bottom: 0.5rem;
    }

    & ul,
    & ol {
        margin-top: 1rem;
        margin-bottom: 1rem;
        padding-left: 1.5rem;
    }

    & li {
        margin-top: 0.25rem;
        margin-bottom: 0.25rem;
    }

    & hr {
        margin-top: 1.75rem;
        margin-bottom: 1.75rem;
        border-color: var(--border--0);
        border-top-width: 1px;
        border-bottom-width: 0;
    }
}

/* Scrollbar Hide - Hides scrollbars while maintaining scroll functionality */
@utility scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
    &::-webkit-scrollbar {
        display: none;
    }
}

/*
 * Enter/Exit Animation System
 *
 * A composable animation system for enter/exit transitions. Based on tw-animate-css by Luca Bosin (MIT).
 * Uses CSS custom properties so utilities compose together:
 *   animate-in fade-in-0 zoom-in-95 slide-in-from-top-2
 *
 * How it works:
 * - `animate-in` applies the `enter` keyframe which reads from --enter-* properties
 * - `animate-out` applies the `exit` keyframe which reads from --exit-* properties
 * - Individual utilities (fade-in, zoom-in, slide-in-from-*) set those properties
 * - @property declarations prevent inheritance so animations don't leak to children
 */

/* @property declarations to prevent inheritance */
@property --enter-opacity {
    syntax: '*';
    inherits: false;
    initial-value: 1;
}
@property --enter-scale {
    syntax: '*';
    inherits: false;
    initial-value: 1;
}
@property --enter-translate-x {
    syntax: '*';
    inherits: false;
    initial-value: 0;
}
@property --enter-translate-y {
    syntax: '*';
    inherits: false;
    initial-value: 0;
}
@property --exit-opacity {
    syntax: '*';
    inherits: false;
    initial-value: 1;
}
@property --exit-scale {
    syntax: '*';
    inherits: false;
    initial-value: 1;
}
@property --exit-translate-x {
    syntax: '*';
    inherits: false;
    initial-value: 0;
}
@property --exit-translate-y {
    syntax: '*';
    inherits: false;
    initial-value: 0;
}

@theme inline {
    /* Percentage values for zoom and slide utilities */
    --percentage-0: 0;
    --percentage-5: 0.05;
    --percentage-10: 0.1;
    --percentage-15: 0.15;
    --percentage-20: 0.2;
    --percentage-25: 0.25;
    --percentage-30: 0.3;
    --percentage-35: 0.35;
    --percentage-40: 0.4;
    --percentage-45: 0.45;
    --percentage-50: 0.5;
    --percentage-55: 0.55;
    --percentage-60: 0.6;
    --percentage-65: 0.65;
    --percentage-70: 0.7;
    --percentage-75: 0.75;
    --percentage-80: 0.8;
    --percentage-85: 0.85;
    --percentage-90: 0.9;
    --percentage-95: 0.95;
    --percentage-100: 1;
    --percentage-translate-full: 1;

    /* Animation shorthand variables */
    --animate-in: enter var(--animation-duration, var(--tw-duration, 150ms)) var(--tw-ease, ease)
        var(--animation-delay, 0s) var(--animation-iteration-count, 1) var(--animation-direction, normal)
        var(--animation-fill-mode, none);
    --animate-out: exit var(--animation-duration, var(--tw-duration, 150ms)) var(--tw-ease, ease)
        var(--animation-delay, 0s) var(--animation-iteration-count, 1) var(--animation-direction, normal)
        var(--animation-fill-mode, none);

    /* Enter keyframe — reads from --enter-* properties */
    @keyframes enter {
        from {
            opacity: var(--enter-opacity, 1);
            transform: translate3d(var(--enter-translate-x, 0), var(--enter-translate-y, 0), 0)
                scale3d(var(--enter-scale, 1), var(--enter-scale, 1), var(--enter-scale, 1))
                rotate(var(--enter-rotate, 0));
        }
    }

    /* Exit keyframe — reads from --exit-* properties */
    @keyframes exit {
        to {
            opacity: var(--exit-opacity, 1);
            transform: translate3d(var(--exit-translate-x, 0), var(--exit-translate-y, 0), 0)
                scale3d(var(--exit-scale, 1), var(--exit-scale, 1), var(--exit-scale, 1)) rotate(var(--exit-rotate, 0));
        }
    }
}

/* Fade — opacity transitions */
@utility fade-in {
    --enter-opacity: 0;
}
@utility fade-in-* {
    --enter-opacity: calc(--value(number) / 100);
    --enter-opacity: --value(--percentage-*, [*]);
}
@utility fade-out {
    --exit-opacity: 0;
}
@utility fade-out-* {
    --exit-opacity: calc(--value(number) / 100);
    --exit-opacity: --value(--percentage-*, [*]);
}

/* Zoom — scale transitions */
@utility zoom-in {
    --enter-scale: 0;
}
@utility zoom-in-* {
    --enter-scale: calc(--value(number) * 1%);
    --enter-scale: calc(--value(ratio));
    --enter-scale: --value(--percentage-*, [*]);
