/* ============================================================================
 * Custom Animations
 * ============================================================================ */

/* Transition Timing Utilities */
@theme {
    /* Exponential easing for smooth, natural feeling animations */
    --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
    /* Softer exponential easing for more subtle transitions */
    --ease-soft-out-expo: cubic-bezier(0.25, 0, 0, 1);
}
@utility ease-out-expo {
    transition-timing-function: var(--ease-out-expo);
}
@utility ease-soft-out-expo {
    transition-timing-function: var(--ease-soft-out-expo);
}

/* Centered Modal Animations - Used for modals/dialogs that appear centered on screen */
@keyframes enter-centered {
    from {
        opacity: 0;
        scale: 0.95;
    }
    to {
        opacity: 1;
        scale: 1;
    }
}
@keyframes exit-centered {
    from {
        opacity: 1;
        scale: 1;
    }
    to {
        opacity: 0;
        scale: 0.95;
    }
}
@utility animate-in-centered {
    translate: -50% -50%;
    animation: enter-centered 200ms ease-out both;
}
@utility animate-out-centered {
    translate: -50% -50%;
    animation: exit-centered 200ms ease-in both;
}

/* Accordion - Used with Radix UI Accordion component which provides --radix-accordion-content-height */
@theme {
    --animate-accordion-down: accordion-down 0.2s ease-out;
    --animate-accordion-up: accordion-up 0.2s ease-out;
}
@keyframes accordion-down {
    from {
        height: 0;
    }
    to {
        height: var(--radix-accordion-content-height);
    }
}
@keyframes accordion-up {
    from {
        height: var(--radix-accordion-content-height);
    }
    to {
        height: 0;
    }
}

/* Blink Animations - Continuous pulsing opacity effect for attention-grabbing elements */
/* Creates a "breathing" effect with smooth fade in/out cycles */
/* Use cases: Loading indicators, notifications, status badges */
@theme {
    --animate-blink: blink 1.3s ease-in-out infinite;

    /* Blink Once - Single pulse animation for one-time attention grab */
    /* Use cases: New message indicator, flash notification, success confirmation */
    --animate-blink-once: blink-once 500ms linear;
}
@keyframes blink {
    0% {
        opacity: 1;
    }
    20%,
    50% {
        opacity: 0;
    }
    70%,
    100% {
        opacity: 1;
    }
}
@keyframes blink-once {
    0% {
        opacity: 1;
    }
    50% {
        opacity: 0.25;
    }
    100% {
        opacity: 1;
    }
}
@utility animate-blink {
    animation: var(--animate-blink);
}
@utility animate-blink-once {
    animation: var(--animate-blink-once);
}

/* Caret Blink - Used for the fake caret in InputCode (OTP/verification code input) */
/* Smoother step-like blink that mimics a real text cursor */
@theme {
    --animate-caret-blink: caret-blink 1.05s ease-out infinite;
}
@keyframes caret-blink {
    0%,
    70%,
    100% {
        opacity: 1;
    }
    20%,
    50% {
        opacity: 0;
    }
}
@utility animate-caret-blink {
    animation: var(--animate-caret-blink);
}

/* Autofill detection. Browser autofill and password managers write straight to an
   input's DOM value, firing no React event — so an uncontrolled field's form store
   never learns the value and validates it as empty on submit. There is no reliable
   cross-browser autofill *event*, but browsers match the `:autofill` pseudo-class
   (Chrome/Safari's `:-webkit-autofill`, supported by Firefox too) the instant they
   fill a field, so we attach this keyframe to that pseudo-class (via
   inputCommonAutofillClassNames in InputTheme.ts). The resulting `animationstart`
   fires the moment autofill lands; FormUncontrolledInputSynchronizer listens for it
   (matching on this animation's name) and reads the DOM value into the store live.
   The animation changes nothing visually — its only job is to raise the event. The
   custom property exists solely so the keyframes aren't empty; minifiers strip empty
   keyframe rules, which would silently kill the event in production. */
@keyframes structureInputAutofillStart {
    from {
        --structure-input-autofill: 0;
    }
    to {
        --structure-input-autofill: 1;
    }
}

/* Split-header table sync. Both keyframes ride the same scroll-timeline
   declared on the table body (`--body-horizontal-scroll-timeline`). The
   timeline maps body `scrollLeft` 0 → max linearly across 0% → 100%, so
   `--scroll-max` (the body's max scrollLeft, written on the table root
   by ResizeObserver) is the pixel target both animations interpolate to.

   `table-header-mirror-x` runs on the header follower div: as the body
   scrolls right, it translates left, tracking 1:1 in the same paint
   frame as the body's native scroll (compositor-thread, zero seam at
   any refresh rate).

   `table-pinned-header-cell-counter-x` runs on each pinned `<th>`:
   translates right by the same amount, canceling the parent follower's
   translation so the pinned cell stays planted at the pinned edge while
   non-pinned cells slide. Body pinned cells use native `position: sticky`
   instead — the header's overflow:hidden wrapper has no scroll context.

   Browsers without scroll-driven support (Firefox without the pref) leave
   both animations inert; TableRoot's feature-detected JS-sync handler
   mirrors `scrollLeft` to `transform` the old way. */
@keyframes table-header-mirror-x {
    from {
        transform: translate3d(0, 0, 0);
    }
    to {
        transform: translate3d(calc(-1 * var(--scroll-max, 0px)), 0, 0);
    }
}
@keyframes table-pinned-header-cell-counter-x {
    from {
        transform: translate3d(0, 0, 0);
    }
    to {
        transform: translate3d(var(--scroll-max, 0px), 0, 0);
    }
}

